const closures=[];for(let e=0;e<3;e++)closures.push(function(){return e});print("let closures each see own i:",closures.map(function(e){return e()}).join(","));const closures2=[];for(let e=0;e<3;e++)for(let s=0;s<2;s++)closures2.push(function(){return e+":"+s});print("nested let closures:",closures2.map(function(e){return e()}).join(" | "));